function kIcon(k){return '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+KI[k]+'</svg>';}
function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var DP_G=[{k:'font',label:'Font',o:[['std','Standard'],['easy','Easy-read']]},{k:'size',label:'Text size',o:[['std','Standard'],['l','Larger'],['xl','Largest']]},{k:'space',label:'Spacing',o:[['std','Standard'],['roomy','Roomy']]}];
var DP_SUN='<svg viewBox="0 0 20 20" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><circle cx="10" cy="10" r="3.6"/><path d="M10 1.8v2M10 16.2v2M1.8 10h2M16.2 10h2M4.2 4.2l1.4 1.4M14.4 14.4l1.4 1.4M4.2 15.8l1.4-1.4M14.4 5.6l1.4-1.4"/></svg>';
function dpPanel(id,cls){return '<section id="'+id+'" class="dprefs-panel'+(cls||'')+'" role="dialog" aria-modal="false" aria-labelledby="'+id+'-h"'+(cls?'':' hidden')+'><p id="'+id+'-h" class="dprefs-title">Reading options</p>'+DP_G.map(function(g){return '<div class="dprefs-group" role="group" aria-labelledby="'+id+'-'+g.k+'"><span id="'+id+'-'+g.k+'" class="dprefs-label">'+g.label+'</span><span class="dprefs-btns">'+g.o.map(function(o){return '<button type="button" data-k="'+g.k+'" data-v="'+o[0]+'" aria-pressed="'+(o[0]==='std')+'">'+o[1]+'</button>';}).join('')+'</span></div>';}).join('')+'<div class="dprefs-actions"><button type="button" data-reset>Reset</button><button type="button" data-close>Close</button></div></section>';}
function dpRow(pid){return '<div class="dprefs"><button type="button" class="dprefs-theme" aria-pressed="false">'+DP_SUN+'<span class="dprefs-ttl">Dark mode</span><span class="dprefs-trk" aria-hidden="true"></span></button><button type="button" class="dprefs-aa" aria-expanded="false" aria-controls="'+pid+'" aria-label="Reading options"><span aria-hidden="true">Aa</span></button></div>';}
function kitDisplayPrefs(row,panel,key){var d=document.documentElement,K={font:'data-font',size:'data-size',space:'data-space',theme:'data-theme'},st={};try{st=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch(e){}
var tg=row.querySelector('.dprefs-theme'),aa=row.querySelector('.dprefs-aa'),mq=window.matchMedia&&matchMedia('(prefers-color-scheme: light)');function dark(){return st.theme?st.theme==='dark':!(mq&&mq.matches);}
function apply(){for(var k in K){var v=st[k];v&&v!=='std'?d.setAttribute(K[k],v):d.removeAttribute(K[k]);}tg.setAttribute('aria-pressed',String(dark()));panel.querySelectorAll('button[data-k]').forEach(function(b){b.setAttribute('aria-pressed',String(b.dataset.v===(st[b.dataset.k]||'std')));});}
function save(){try{localStorage.setItem(key,JSON.stringify(st));}catch(e){}}
function place(){var r=aa.getBoundingClientRect();panel.style.top=Math.round(r.bottom+8)+'px';var vw=document.documentElement.clientWidth;panel.style.right=Math.max(16,Math.min(Math.round(vw-r.right),vw-panel.offsetWidth-16))+'px';}
function open(o){panel.hidden=!o;aa.setAttribute('aria-expanded',String(o));if(o){place();(panel.querySelector('button[aria-pressed="true"]')||panel.querySelector('button')).focus();}else aa.focus();}
tg.onclick=function(){st.theme=dark()?'light':'dark';save();apply();};aa.onclick=function(){open(panel.hidden);};
panel.addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))open(false);else if(b.hasAttribute('data-reset')){st={};save();apply();}else if(b.dataset.k){st[b.dataset.k]=b.dataset.v;save();apply();}});
document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!panel.hidden)open(false);});addEventListener('resize',function(){if(!panel.hidden)place();});addEventListener('scroll',function(){if(!panel.hidden)place();},{passive:true});apply();}
var stg=kSlot();stg.innerHTML='<div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap"><span style="font-family:var(--ds-font-mono);letter-spacing:.18em;font-weight:700">ARCS FIELD OS</span>'+dpRow('dp-stage')+'</div>';document.body.insertAdjacentHTML('beforeend',dpPanel('dp-stage'));kitDisplayPrefs(stg.querySelector('.dprefs'),document.getElementById('dp-stage'),'arcsKitRead');
STATES.forEach(function(s,i){var el=kSlot(i);if(s[0]==='row'){el.innerHTML=dpRow('dp-x'+i).replace('class="dprefs"','class="dprefs" inert');return;}el.innerHTML=dpPanel('dp-s'+i,' is-static');el.querySelector('section').setAttribute('inert','');});
